def calculate_euclidean_distance(points):
    # Calculate sum of squared distances from origin
    total = 0
    for x, y in points:
        total += (x ** 2 + y ** 2) ** 0.5
    return total

def calculate_manhattan_distance(points):
    # Calculate sum of Manhattan distances from origin
    total = 0
    for x, y in points:
        total += abs(x) + abs(y)
    return total

